;; clojure.core.async.impl.protocols — the port protocol upstream's channel
;; types implement, for the ported code that asks about it.
;;
;; jolt's channels are native (host/chez/java/async.ss), so nothing here is
;; generated by a defprotocol over a channel type. A port asks one of two
;; questions — (:import (clojure.core.async.impl.protocols ReadPort)) and
;; (satisfies? clojure.core.async.impl.protocols/ReadPort ch) — and both need a
;; namespace to answer them, which is what this one is for.
;;
;; ReadPort alone is deliberate. It is the only name ported code imports from
;; here, and the protocol METHOD is never called: callers reach for
;; clojure.core.async/take! and friends directly. WritePort, Channel and
;; MAX-QUEUE-SIZE are upstream's too, and are not reproduced until something
;; needs them.
;;
;; No :require of clojure.core.async. Its vars are installed natively at boot
;; and the names below are spelled in full; a require would only close a cycle,
;; since the overlay (stdlib/clojure/core/async.clj) requires THIS namespace.
;; Upstream's file has the same shape, minus the cycle.
(ns clojure.core.async.impl.protocols
  (:require [jolt.host :as host]))

(defprotocol ReadPort
  (take! [port handler] "derefable val if taken, nil if take was enqueued"))

;; A channel reports the class name upstream's ManyToManyChannel has — that is
;; the class-arm in host/chez/java/async.ss — but the class graph carries no row
;; for the name, and value-host-tags, the list protocol dispatch looks a value up
;; by, is derived from that graph. Without a row, the extend-type below files its
;; impl under no tag a channel has and (satisfies? ReadPort ch) stays false.
;;
;; The supers list is empty on purpose: the class name is the only tag that earns
;; a place here, since dispatch looks up that same name. Naming the interfaces
;; upstream's class implements would not answer (instance? ReadPort ch) — that
;; goes through the instance check below — and nothing else asks.
(host/register-class-supers!
 "clojure.core.async.impl.channels.ManyToManyChannel" [])

;; (:import (clojure.core.async.impl.protocols ReadPort)) does not load a
;; namespace, and instance-check does not consult the class graph, so the key
;; (instance? ReadPort ch) lowers to has to be answered directly. Both spellings
;; are registered: the ns/Name key an unqualified symbol resolves to, and the
;; dotted class spelling.
;;
;; `when`, not the `and` it resembles. The registry reads nil as "not mine, ask
;; the next check" and anything non-nil as final, so an `and` — which returns
;; false for every name it does not own — would stop the walk and veto the
;; instance checks registered after this one (jolt.socket, jolt.time and
;; java.time all register checks).
(clojure.core/__register-instance-check!
 (fn [class-name val]
   (when (and (contains? #{"clojure.core.async.impl.protocols.ReadPort"
                           "clojure.core.async.impl.protocols/ReadPort"}
                         class-name)
              (clojure.core.async/chan? val))
     true))
 ;; the claim: it answers only for these names, so instance? of any other class
 ;; never calls it and its verdict stays memoized
 {:classes #{"clojure.core.async.impl.protocols.ReadPort"
             "clojure.core.async.impl.protocols/ReadPort"}})

;; The method body is load-bearing, not decoration: extend-type with no methods
;; registers no impl at all, and satisfies? stays false.
(extend-type clojure.core.async.impl.channels.ManyToManyChannel
  ReadPort
  (take! [port f] (clojure.core.async/take! port f)))

;; --- a port that is not a channel ----------------------------------------------
;; Upstream reads every port through take! above; jolt's take entry points go
;; straight to the native channel, so they ask the reader installed here first
;; (host/chez/java/async.ss, jolt-async-port).

(defn read-port
  "A promise-chan holding what port answers, port a value implementing ReadPort that
  is not one of jolt's channels (a reify, as Datahike's write results are): read as
  upstream reads every port, through take!, given a fn of the value (jolt has no
  Handler protocol: a channel's take! calls the fn, so a port that delegates to one
  works). A take! that answers a deref-able box (upstream's convention for a value
  ready now) is read from the box; nil closes the promise-chan. Every take entry point
  (<!, <!!, take!, poll!, alts!, the go pass's parks) reads such a port through this.
  A take commits when it is asked, so alts! over such a port takes from it once even
  when another port wins: a promise answers the same value again, and a channel-like
  port loses that value. poll! and alts!'s ready scan see the value only when the
  port's take! delivers it at once (a promise-chan's does)."
  [port]
  (let [c (clojure.core.async/promise-chan)
        f (fn [v] (if (nil? v) (clojure.core.async/close! c) (clojure.core.async/put! c v)))
        b (take! port f)]
    (when (some? b) (f @b))
    c))

(clojure.core.async/__set-port-reader! (fn [x] (if (satisfies? ReadPort x) (read-port x) x)))

